import { _decorator, Component, Node } from 'cc';
import { Entity } from './Engine/Entity';
import { Bus } from './Engine/Bus';
const { ccclass, property } = _decorator;

class TestEntity extends Entity{
    readonly kind = 'jojo';
    public vx = 10;
}
@ccclass('TestRunner')
export class TestRunner extends Component {
    start() {
       const e1:TestEntity = new TestEntity();
       const e2:TestEntity = new TestEntity();

       console.log(e1.kind,e2.kind);
       console.log(e1.id,e2.id);

       const bus = new Bus();


       bus.on('ping',(id,kind)=>{console.log(id,kind)});

       bus.emit('ping',e1.id,e1.kind);

        const busA = new Bus();
        const busB = new Bus();

        busA.on('hello', () => console.log('A 收到 hello'));
        busB.on('hello', () => console.log('B 收到 hello'));

        busA.emit('hello');  // 只应该 A 收到
        console.log('--- 上面只打了一条，说明 A/B 是隔离的 ---');

    }


}


